{{-- 1. Bảo vệ Form truyền thống trong Blade --}}
<form method="POST" action="/api/v1/bank-transfer">
    {{-- Directive @csrf sinh thẻ ẩn chứa CSRF Token của session hiện tại --}}
    @csrf

    <input type="text" name="recipient_account" required />
    <input type="number" name="amount" required />
    <button type="submit">Chuyển tiền an toàn</button>
</form>

{{-- 2. Cấu hình gửi AJAX / SPA qua Header trong JavaScript --}}
<script>
// Lấy CSRF token từ meta tag nếu dùng Fetch API thủ công
const csrfToken = document.querySelector('meta[name="csrf-token"]').getAttribute('content');

fetch('/api/v1/bank-transfer', {
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'X-CSRF-TOKEN': csrfToken // Laravel VerifyCsrfToken middleware sẽ kiểm tra header này
    },
    body: JSON.stringify({ recipient_account: '99998888', amount: 500000 })
});
</script>
